# AI Office v2.3 Part A Conversational Intake Architecture Installer
$ErrorActionPreference="Stop"
$Repository="E:\AI\AI-Office"
if(-not(Test-Path -LiteralPath $Repository -PathType Container)){throw "AI Office repository not found at E:\AI\AI-Office"}
Set-Location $Repository
$Timestamp=Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory=Join-Path $Repository ("workspace\installer-backups\v2.3-part-a-"+$Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force|Out-Null
foreach($Directory in @("config\conversational-office","workspace\conversational-office\sessions","workspace\conversational-office\messages","workspace\conversational-office\turns","workspace\conversational-office\indexes","workspace\templates","scripts\conversational-office","docs")){New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force|Out-Null}
function Write-EmbeddedFile{param([string]$RelativePath,[string]$Base64Content);$Destination=Join-Path $Repository $RelativePath;$Parent=Split-Path -Parent $Destination;if($Parent-and-not(Test-Path $Parent)){New-Item -ItemType Directory -Path $Parent -Force|Out-Null};if(Test-Path $Destination){$BackupPath=Join-Path $BackupDirectory $RelativePath;$BackupParent=Split-Path -Parent $BackupPath;if($BackupParent-and-not(Test-Path $BackupParent)){New-Item -ItemType Directory -Path $BackupParent -Force|Out-Null};Copy-Item $Destination $BackupPath -Force};[IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content));Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green}
